# owner: platform
import unittest
from datetime import date

from rosterkit.notices import absence_notice
from rosterkit.models import Mark, Student


STUDENT = Student("1001", "Thistle", "Bram", "A")


def mark(day, status="absent", who="1001"):
    return Mark(who, date(2026, 10, day), status)


class NoticeTests(unittest.TestCase):
    def test_names_count_and_ordered_dates(self):
        text = absence_notice(
            STUDENT,
            [mark(9), mark(2), mark(5, "present")]
        )
        self.assertEqual(
            text,
            "Bram Thistle was absent for 2 day(s): "
            "2026-10-02, 2026-10-09."
        )

    def test_other_student_mark_is_rejected(self):
        with self.assertRaises(ValueError):
            absence_notice(
                STUDENT, [mark(2), mark(3, who="9")]
            )

    def test_no_absences_is_rejected(self):
        with self.assertRaises(ValueError):
            absence_notice(STUDENT, [mark(2, "late")])
